try {
  log("读取并校验 " + asarPath);
  let p = asar.readEntry(asarPath, PRELOAD_REL);
  let m = asar.readEntry(asarPath, MAIN_REL);
  let r = asar.readEntry(asarPath, RENDER_REL);
  if (p == null || m == null || r == null) die("目标文件缺失，ZCode 版本可能不兼容此补丁");
  p = p.toString("utf8"); m = m.toString("utf8"); r = r.toString("utf8");
  if (p.includes("modelhubFetchModels") || r.includes("__mhPick")) die("检测到已安装过补丁，如需重装请先运行 还原补丁.cmd");

  if (!p.includes(PRELOAD_ANCHOR)) die("preload 锚点不匹配，ZCode 版本不兼容");
  if (r.split(ORIG_ADD_BTN).length - 1 !== 1) die("渲染层锚点A不匹配，ZCode 版本不兼容");
  if (r.split(ORIG_QPT).length - 1 !== 1) die("渲染层锚点B不匹配，ZCode 版本不兼容");

  log("备份原版 -> app.asar.modelhub-backup");
  if (!fs.existsSync(backupPath)) fs.copyFileSync(asarPath, backupPath);

  log("改写三个文件（内存中完成）...");
  p = p.replace(PRELOAD_ANCHOR, 'exposeInMainWorld("zcode",{' + PRELOAD_INJECT + "connectRemote");
  m += MAIN_HANDLERS;
  r = r.replace(ORIG_ADD_BTN, ADD_BTN + "," + ORIG_ADD_BTN);
  r = r.replace(ORIG_QPT, EDIT_WRAP);
  r += HELPER_BLOCK;

  log("外科手术式重打包（数据区原样搬运，仅追加改动）...");
  const outTmp = asarPath + ".modelhub-new";
  asar.patchEntries(asarPath, outTmp, {
    [PRELOAD_REL]: Buffer.from(p, "utf8"),
    [MAIN_REL]: Buffer.from(m, "utf8"),
    [RENDER_REL]: Buffer.from(r, "utf8"),
  });
  fs.copyFileSync(outTmp, asarPath);
  fs.rmSync(outTmp, { force: true });
  console.log("\n[√] 补丁安装完成！打开 ZCode：设置 → 模型供应商 → 添加/编辑渠道，即可看到「拉取模型」按钮。");
} catch (e) {
  die(String(e && e.stack || e));
}
